    "home.card_food_desc": "• เมนูอาหารไทยและนานาชาติพร้อมภาพถ่าย\n• ตะกร้าสินค้าโต้ตอบและปรับระดับความเผ็ดได้\n• ระบบจัดส่งออเดอร์และส่งเสียงช่วยสั่งอาหารเรียลไทม์",
