    "home.card_alldemo_title": "พอร์ทัลรวมเดโมทั้งหมด",
    "home.card_alldemo_desc": "• ศูนย์รวมระบบจำลองแซนด์บอกซ์ทั้งหมด (จองเที่ยวบิน, ร้านค้าไอที, สั่งอาหาร, จองโรงแรม)\n• รวบรวมผลงานโครงการเว็บแอปพลิเคชันจากทีมพัฒนา StartUP (TN01–TN20)\n• ระบบค้นหา กรองหมวดหมู่ และเปิดดูตัวอย่างเว็บไซต์จำลองจริง",
    "home.card_alldemo_cta": "เปิดพอร์ทัลรวมเดโม",
