    "home.card_itstore_cta": "เปิดร้านไอทีจำลอง",
    "home.card_hotel_title": "โรงแรม Botnoi",
    "home.card_hotel_desc": "• ค้นหาห้องพักและเช็คสถานะห้องว่างเรียลไทม์\n• เลือกวันเข้าพักและคำนวณราคาอัตโนมัติ\n• ระบบยืนยันการจองและออกใบรับรองครบวงจร",
