    "home.card_contact_desc": "• แบบฟอร์มเก็บข้อมูลผู้สนใจระบบรองรับการตรวจสอบข้อมูลอินพุต\n• เลือกประเภทการสอบถามข้อมูลด้วย Dropdown ไดนามิก และ FAQ แบบ Accordion\n• ระบบตารางรายชื่อและบันทึกผู้ติดต่อสำหรับผู้ดูแลระบบ",
