    "detail.flight.desc": "Botnoi Air เป็นเอไออวาตาร์อัจฉริยะสำหรับบริการสายการบินยุคใหม่ ช่วยผู้โดยสารค้นหาเที่ยวบินเรียลไทม์ เลือกที่นั่ง คำนวณราคาตั๋ว ตรวจสอบสัมภาระ และออกบอร์ดดิ้งพาสอิเล็กทรอนิกส์ได้ทันที",
    "detail.flight.feat1": "ค้นหาเที่ยวบินเรียลไทม์และผังเลือกที่นั่งโต้ตอบ",
    "detail.flight.feat2": "ระบบจองตั๋วและสลับภาษาด้วยเสียงสังเคราะห์",
    "detail.flight.feat3": "คำนวณน้ำหนักสัมภาระและอัตราค่าตั๋วบินอัตโนมัติ",
    "detail.flight.feat4": "ออกเอกสาร E-Ticket PDF และส่งอีเมลยืนยันทันที",

    "detail.food.desc": "Botnoi Food Express ยกระดับการสั่งอาหารด้วยเมนูดิจิทัลและระบบช่วยสั่งด้วยเสียง ลูกค้าสามารถเลือกอาหารไทยและนานาชาติ ปรับระดับความเผ็ด ระบุข้อจำกัดทางการทาน และส่งออเดอร์ไปยังห้องครัวได้เรียลไทม์",
    "detail.food.feat1": "รายการเมนูอาหารไทยและนานาชาติพร้อมภาพถ่าย",
    "detail.food.feat2": "ตะกร้าสั่งอาหารด้วยเสียงและปรับระดับความเผ็ด",
    "detail.food.feat3": "ระบบระบุแพ้อาหารและความต้องการพิเศษ",
    "detail.food.feat4": "ออกตั๋วออเดอร์และสรุปใบเสร็จสั่งอาหารเรียลไทม์",

    "detail.itstore.desc": "IT Store E-Commerce Avatar ทำหน้าที่เป็นผู้เชี่ยวชาญด้านไอที คอยแนะนำแล็ปท็อป เปรียบเทียบสเปกคอมพิวเตอร์ (RAM, CPU, GPU) เช็กสต็อกสินค้า และช่วยลูกค้าตัดสินใจซื้อด้วย AI",
    "detail.itstore.feat1": "ระบบเปรียบเทียบสเปกอุปกรณ์ไอที (CPU, RAM, SSD)",
    "detail.itstore.feat2": "ตรวจสอบสต็อกสินค้าและราคาร้านค้าเรียลไทม์",
    "detail.itstore.feat3": "ระบบ AI แนะนำสินค้าและอุปกรณ์อัปเกรดที่เหมาะสม",
    "detail.itstore.feat4": "ตะกร้าสินค้าโต้ตอบและชำระเงินออนไลน์",

    "detail.hotel.desc": "Botnoi Hotel Concierge ต้อนรับผู้เข้าพักตลอด 24 ชั่วโมง ช่วยตรวจสอบห้องพักว่าง เลือกวันเข้าพัก ดูสิ่งอำนวยความสะดวก แจ้งคำขอพิเศษ และออกใบยืนยันการจองได้ทันที",
    "detail.hotel.feat1": "เปรียบเทียบประเภทห้องพักและสิ่งอำนวยความสะดวก",
    "detail.hotel.feat2": "ปฏิทินเลือกวัน Check-in / Check-out อัตโนมัติ",
    "detail.hotel.feat3": "บันทึกคำขอพิเศษและบริการรถรับส่งสนามบิน",
    "detail.hotel.feat4": "ออกใบยืนยันการจองและวอยเชอร์ที่พักทันที",

    "detail.contact.desc": "โซลูชัน WebAvatar สำหรับองค์กร B2B ในกลุ่มธนาคาร โทรคมนาคม การแพทย์ และค้าปลีก สามารถเชื่อมต่อเข้ากับระบบ ERP, CRM และฐานข้อมูลเดิมขององค์กรได้อย่างสมบูรณ์",
    "detail.contact.feat1": "เชื่อมต่อระบบ ERP, CRM และ API หลังบ้านเดิม",
    "detail.contact.feat2": "รองรับการติดตั้งหลายช่องทาง (Web, iOS, Android, Kiosk)",
    "detail.contact.feat3": "รับประกันการดูแลระดับ Enterprise SLA และวิศวกรดูแลส่วนตัว",
    "detail.contact.feat4": "มาตรฐานความปลอดภัยระดับสากล SOC2 และ ISO27001",

    "detail.alldemo.desc": "ศูนย์รวมพอร์ทัลผลงานและแอปพลิเคชันแซนด์บอกซ์ทั้งหมดของ WebAvatar Engine ทดลองใช้งานระบบ Event-Driven Routing, Focus Hooks, Input Validation และ Voice Synthesis ในที่เดียว",
    "detail.alldemo.feat1": "เข้าถึงระบบจำลองโต้ตอบทั้ง 5 เคสธุรกิจ",
    "detail.alldemo.feat2": "ระบบตรวจสอบ Event และ Telemetry เรียลไทม์",
    "detail.alldemo.feat3": "เครื่องมือทดสอบเสียงพูดและปรับ Pitch เสียงอวาตาร์",
    "detail.alldemo.feat4": "สนามทดลอง State Management และ Focus Hooks",

    "detail.overview": "ภาพรวมและรายละเอียด",
    "detail.features": "คุณสมบัติเด่นและฟังก์ชัน AI",
    "detail.specs": "ข้อมูลทางเทคนิคของกลไก",
