    "home.tech_title": "กลไก WebAvatar",
    "home.tech_subtitle": "การประมวลผลและการใช้งานร่วมกับหน้าเว็บ",
    "home.tech_desc": "แตกต่างจากแชทบอทข้อความทั่วไป WebAvatar วิเคราะห์โครงสร้าง DOM และโต้ตอบกับปุ่มต่าง ๆ บนจอโดยตรง เพื่อการนำทางที่ราบรื่นและใช้ข้อมูลโทเคนอย่างคุ้มค่า ผ่านหลักการดังนี้:",
    "home.rule1_title": "การนำทางด้วย Event",
    "home.rule1_desc": "• ส่ง CustomEvent 'webavatar-navigate' เมื่อต้องการเปลี่ยนหน้าเว็บ\n• ดักจับระบบนำทางแบบ SPA เพื่ออัปเดต React Router แบบไดนามิก\n• ป้องกันการรีโหลดหน้าใหม่และรักษาการสนทนาด้วยเสียงให้อยู่ครบ",
    "home.rule2_title": "โฟกัสเป้าหมายเชิงประกาศ",
    "home.rule2_desc": "• ยึดโยงปุ่มสำคัญด้วย ID เฉพาะ (เช่น #nav-flight, #nav-contact)\n• สั่งให้เลื่อนหน้าจอไปยังตำแหน่งเป้าหมายอย่างนุ่มนวล\n• แสดงเอฟเฟกต์วงแหวนสีรอบปุ่มและไฮไลต์สอดคล้องกับเสียงพูด",
    "home.rule3_title": "การกรอกข้อมูลและตรวจสอบแบบไดนามิก",
    "home.rule3_desc": "• เชื่อมต่อฟอร์มฝั่งลูกค้ากับการตรวจสอบมาตรฐาน HTML5\n• ยิงคำสั่งเปลี่ยนค่า inputs ดั้งเดิมเพื่ออัปเดต State ของ React\n• แสดงสถานะการกรอกข้อมูลและแจ้งเตือนความสำเร็จแบบเรียลไทม์",
    "home.tech_cta": "ติดตั้ง WebAvatar บนเว็บไซต์ของคุณ",
    "home.features_heading": "คุณสมบัติและข้อจำกัดของกลไก",
    "home.feat1": "รองรับการแบ่งวรรคและตัดคำภาษาไทย",
