    "itstore_item.probook.desc": "แล็ปท็อประดับพรีเมียมสำหรับผู้ใช้งานหนักและนักสร้างสรรค์ ประสิทธิภาพสูงสุดพร้อมแบตเตอรีอึดทนทั้งวัน",
