    "itstore_item.curve32.desc": "จอโค้ง 4K ความละเอียดสูงพร้อมอัตรารีเฟรชสูง เหมาะกับทั้งเกมมิ่งและทำงานหนักในจอเดียว",
    "itstore_item.mechkey.name": "BotnKey Mechanic Pro",
    "itstore_item.mechkey.specs": "Full-size · Cherry MX Red · RGB · PBT Keycaps",
    "itstore_item.mechkey.desc": "แป้นพิมพ์กลไกสวิตช์เชอร์รีแดง ให้สัมผัสการกดที่นุ่มนวลและตอบสนองเร็ว เหมาะโค้ดดิ้งและเล่นเกม",
