    "itstore_item.mate80pro.name": "HUAWEI Mate 80 Pro",
    "itstore_item.mate80pro.specs": "หน้าจอ LTPO OLED 6.75 นิ้ว · RAM 16GB + ROM 512GB · กล้อง 3 ตัว 50MP",
    "itstore_item.mate80pro.desc": "HUAWEI Mate 80 Pro มาพร้อมหน้าจอ LTPO OLED ขนาด 6.75 นิ้ว (2832×1280, 1-120Hz), ตัวเครื่องบาง 7.95 มม. น้ำหนัก 219 กรัม พร้อมมาตรฐานกันน้ำกันฝุ่นระดับ IP68/IP69, ชิปความจุ RAM 16 GB + ROM 512 GB, แบตเตอรี่ 5,750 mAh รองรับชาร์จไวผ่านสาย 100W และชาร์จไร้สาย 80W, กล้องหลัก 50 MP (รูรับแสงปรับได้ F1.4–F4.0, OIS), Ultra-Wide 40 MP และ Telephoto Macro 48 MP (OIS, ซูมออปติคัล 4× / ดิจิทัล 100×) กล้องหน้ามีความละเอียด 13 MP พร้อมระบบ Auto Focus",
    "itstore_item.matex7.name": "HUAWEI Mate X7",
    "itstore_item.matex7.specs": "หน้าจอพับ OLED 8.0 นิ้ว · RAM 16GB + ROM 512GB · กล้อง 50MP",
    "itstore_item.matex7.desc": "HUAWEI Mate X7 เป็นสมาร์ทโฟนจอพับที่มาพร้อมหน้าจอหลัก OLED ขนาด 8 นิ้ว และหน้าจอนอก 6.49 นิ้ว (ทั้งสองจอรองรับ LTPO 1–120Hz), ตัวเครื่องบาง 4.5 มม. เมื่อกางออก (9.5 มม. เมื่อพับ) น้ำหนัก 236 กรัม, RAM 16 GB + ROM 512 GB, แบตเตอรี่ 5,600 mAh รองรับชาร์จไวผ่านสาย 66W และชาร์จไร้สาย 50W, กล้องหลัง 3 ตัว ได้แก่ กล้องหลัก Ultra Lighting 50 MP (รูรับแสงปรับได้ F1.49–F4.0, OIS), กล้อง Ultra-Wide 40 MP และกล้อง Telephoto Macro 50 MP (OIS, ซูมออปติคัล 3.5× / ดิจิทัล 100×) พร้อมกล้องหน้า 8 MP ทั้งบนจอนอกและจอใน",
    "itstore_item.matext.name": "HUAWEI Mate XT ULTIMATE DESIGN",
    "itstore_item.matext.specs": "หน้าจอพับ 3 ทบ OLED 10.2 นิ้ว · ชิป Kirin 9010 · RAM 16GB + ROM 1TB",
    "itstore_item.matext.desc": "HUAWEI Mate XT ULTIMATE DESIGN สมาร์ทโฟนดีไซน์หน้าจอพับ 3 ทบ (Tri-fold) มาพร้อมจอ OLED ปรับเปลี่ยนได้ 3 ขนาด (6.4 นิ้ว / 7.9 นิ้ว / 10.2 นิ้ว) อัตรารีเฟรช 90Hz, ขับเคลื่อนด้วยชิป Kirin 9010 RAM 16 GB + ROM 1 TB, ตัวเครื่องบาง 3.6 มม. เมื่อกางสุด (น้ำหนัก 298 กรัม) กันน้ำ IPX8, แบตเตอรี่ 5,600 mAh รองรับชาร์จไว 66W และชาร์จไร้สาย 50W, กล้องหลัง 3 ตัว นำโดยกล้องหลัก 50 MP (ปรับรูรับแสง F1.4–F4.0, OIS), Ultra-Wide 12 MP และ Telephoto Periscope 12 MP (OIS, ซูมออปติคัล 5.5× / ดิจิทัล 50×) กล้องหน้าความละเอียด 8 MP",
    "itstore_item.matex6.name": "HUAWEI Mate X6",
    "itstore_item.matex6.specs": "หน้าจอพับ OLED 7.93 นิ้ว · ชิป Kirin 9020 · RAM 12GB + ROM 512GB",
    "itstore_item.matex6.desc": "HUAWEI Mate X6 สมาร์ทโฟนจอพับทรงมาพร้อมจอหลัก OLED ด้านในขนาด 7.93 นิ้ว และจอนอก 6.45 นิ้ว (ทั้งสองจอรองรับ LTPO 1–120Hz), ตัวเครื่องบาง 4.6 มม. เมื่อกางออก (9.85–9.9 มม. เมื่อพับ) น้ำหนัก 239 กรัม, ขับเคลื่อนด้วยชิป Kirin 9020 ร่วมกับ RAM 12 GB + ROM 512 GB บนระบบปฏิบัติการ EMUI 15.0, แบตเตอรี่ 5,110 mAh รองรับชาร์จไวผ่านสาย 66W และชาร์จไร้สาย 50W, กล้องหลัง 3 ตัว นำโดยกล้องหลัก 50 MP (ปรับรูรับแสง F1.4–F4.0, OIS), Ultra-Wide 40 MP และ Telephoto Macro 48 MP (OIS, ซูมออปติคัล 4× / ดิจิทัล 100×) พร้อมกล้องหน้าความละเอียด 8 MP ทั้งตอนพับและกางออก",
