    "contact.faq_q1": "WebAvatar คืออะไร และจะติดตั้งเข้ากับหน้าเว็บของฉันได้อย่างไร?",
    "contact.faq_a1": "WebAvatar คือผู้ช่วยตัวแทนดิจิทัลเสมือนจริงที่ทำงานผ่านชุดสคริปต์ JavaScript SDK ขนาดเล็กที่ฝังบนเว็บไซต์ โดยจะลอยตัวโต้ตอบกับ DOM หน้าเว็บ เลื่อนหน้าจอ นำทางหน้าเพจผ่านระบบ Single-Page Application (SPA) และสื่อสารด้วยเสียงพูดสังเคราะห์ประดิษฐ์แก่ผู้เข้าชม",
    "contact.faq_q2": "เสียงพูดสังเคราะห์รองรับภาษาไทยแบบติดกันหรือไม่?",
    "contact.faq_a2": "รองรับอย่างสมบูรณ์แบบ โมเดลเสียงสังเคราะห์ของเราผ่านการเรียนรู้คลังเสียงพูดในไทย ทำให้เข้าใจน้ำเสียง จังหวะวรรคตอน การออกเสียงเชื่อมคำ และสำเนียงที่ดูเป็นธรรมชาติเหมาะกับชาวไทย",
    "contact.faq_q3": "ฉันสามารถเลือกภาพลักษณะของอวตาร์เองได้ไหม?",
    "contact.faq_a3": "ได้แน่นอน บอทน้อย กรุ๊ป สนับสนุนการขึ้นโมเดล 3D แบบคัสตอม ปรับเปลี่ยนอินเทอร์เฟซ และเสื้อผ้าหน้าผม เพื่อสร้างอวตาร์ดิจิทัลที่ถอดแบบมาจากมาสคอตบริษัท บุคคลสำคัญ หรือทูตประจำตราสินค้าของคุณ",
