    "home.tech_title": "WebAvatar 引擎",
    "home.tech_subtitle": "统一代理执行和站点互操作性",
    "home.tech_desc": "与标准的基于文本的机器人不同，WebAvatar 扫描 DOM 并直接与元素交互。它通过遵守以下规则来实现流畅的导航和低令牌开销：",
    "home.rule1_title": "事件驱动路由",
    "home.rule1_desc": "• 调度可取消的“webavatar-navigate”自定义事件进行页面过渡\n• 拦截单页面路由以动态更新 React Router\n• 防止全页重新加载并保持实时语音会话完整",
    "home.rule2_title": "声明性焦点钩子",
    "home.rule2_desc": "• 使用唯一的 DOM ID 锚定元素（例如 #nav-flight、#nav-contact）\n• 动态触发平滑滚动和焦环动画\n• 将视觉突出显示与语音口头表达同步",
    "home.rule3_title": "冗余输入验证",
    "home.rule3_desc": "• 将客户端表单连接到标准 HTML5 输入验证\n• 触发本机输入事件以更新 React 组件状态\n• 提供实时响应式反馈和成功指示器",
    "home.tech_cta": "将 WebAvatar 部署到您的站点",
    "home.features_heading": "发动机特性和限制",
    "home.feat1": "支持连续泰文解析",
