    "showcase.desc_tn05": "• 在线医生预约与科室查询\n• 体检套餐与医疗中心目录\n• 个人健康档案与诊断报告",
    "showcase.desc_tn06": "• 泰语语音转文字、语音合成与声音克隆\n• 对话式 AI 聊天机器人与语言模型 API\n• 开发者 SDK 文档与订阅套餐",
    "showcase.desc_tn07": "• 数字餐饮菜单与在线订座系统\n• 自定义点餐与口味食材微调\n• 实时订单汇总与电子账单",
    "showcase.desc_tn08": "• 虚拟展厅与家具展示目录\n• 室内设计灵感与家居搭配\n• 无缝在线订购与结账",
    "showcase.desc_tn09": "• 实时语音到语音双向翻译\n• 自然语音合成 (TTS) 与音色转换\n• 多语言语音播放与即时翻译",
    "showcase.desc_tn10": "• 空调清洗与维修技术人员预约\n• 透明的服务价格与清洗套餐\n• 实时跟踪技术人员服务状态",
    "showcase.desc_tn11": "• 执业药师在线用药咨询指导\n• 初始症状评估与处方建议\n• 安全送药到家服务",
    "showcase.desc_tn12": "• 房产与住宅搜索平台\n• 虚拟看房与项目展厅目录\n• 在线经纪人咨询与预约看房",
