    "site2026.hero_subtitle": "2026 年 6 月 25 ～ 27 日、クイーン シリキット ナショナル コンベンション センター (QSNCC)",
    "site2026.about_title": "サイト2026について",
    "site2026.about_desc": "国家イノベーション庁 (公的機関) または NIA は、国家イノベーション システムとスタートアップ エコシステムを継続的に開発することの重要性を認識しています。今年のStartup x Innovation Thai Expo 2026（SITE 2026）は、「グローバルイノベーションインパクト：投資の年」というコンセプトの下で開催され、グローバルイノベーションネットワークを結集し、協力を高め、エコシステムを強化するための知識共有を促進します。",
    "site2026.objective_title": "目的",
    "site2026.objective_1": "1. エコシステム内のすべてのセクター（政府、民間、学界、団体）間のイノベーション協力を地域内および国際的に強化する。",
    "site2026.objective_2": "2. ビジネスチャンスを創出し、スタートアップやイノベーションベースの企業を支援します。",
    "site2026.objective_3": "3. 経済拡大を支援するために、東南アジアおよび世界的に国際的なビジネスとイノベーションのネットワークを確立する。",
    "site2026.activities_title": "主な活動",
    "site2026.activity_forum_title": "フォーラム",
    "site2026.activity_forum_desc": "コラボレーション、人工知能、持続可能性に焦点を当て、成功したイノベーション企業の知識とビジネス実践を共有するセミナー。",
    "site2026.activity_exhibition_title": "展示",
    "site2026.activity_exhibition_desc": "ビジネスチャンスを創出し、収益を増やし、投資を刺激するためのイノベーションベースの企業や新興企業を紹介します。",
    "site2026.activity_match_title": "ビジネスマッチング",
    "site2026.activity_match_desc": "スタートアップやイノベーション型企業と大企業の投資創出や事業拡大を目的としたビジネスマッチング活動。",
