    "about.badge": "私たちのアイデンティティ",
    "about.title": "先駆的な会話インテリジェンス",
    "about.subtitle": "Botnoi Group は、高度な人工知能を東南アジアの企業にとってアクセスしやすく、超ローカライズされ、高度にトランザクション化できるようにするという、唯一の使命を持って設立されました。",
    "about.purpose_title": "私たちの目的",
    "about.purpose_desc1": "私たちは、人間と機械のインタラクションは摩擦がなく、自然で、非常に直観的であるべきだと信じています。会話型 NLP、合成人間音響、インタラクティブな 3D デジタル アバターを橋渡しすることで、私たちは明日のデジタル ワークフォースを創出します。",
    "about.purpose_desc2": "高頻度の顧客ケアを自動化する場合でも、複雑な医療ポータルを通じて患者を案内する場合でも、Botnoi Group のソリューションは、妥協のない信頼性で拡張できるように構築されています。",
    "about.vision_title": "私たちのビジョン",
    "about.vision_desc": "東南アジアの音声とデジタルヒューマンテクノロジーの絶対的な標準となること。当社は、地域の中小企業や企業が、優れた顧客満足度を提供する最先端の仮想エージェントを導入できるように支援します。",
    "about.vision_cta": "当社のエンジニアとつながる",
    "about.journey_title": "ボットノイの旅",
    "about.journey_subtitle": "バンコクの AI 専門スタートアップから地域のデジタル ヒューマン リーダーまでの歴史をたどります。",
    "about.timeline_2018_title": "会社設立",
    "about.timeline_2018_desc": "• 言語学者と AI エンジニアによってタイのバンコクに Botnoi Group を設立\n• タイ語解析および自然言語処理 (NLP) モデルの開発に特化",
    "about.timeline_2020_title": "Botnoi AI の起動",
    "about.timeline_2020_desc": "• フラグシップのローコード AI チャットボット プラットフォーム (Botnoi.ai) をリリース\n• LINE OA と Facebook Messenger にわたるカスタマー サポートを自動化\n• 5,000 を超える企業クライアントのカスタマー サポートを強化",
    "about.timeline_2022_title": "Botnoi 音声ロールアウト",
    "about.timeline_2022_desc": "• 最先端の Text-to-Speech (TTS) エンジン (Botnoi Voice) を発表\n• 東南アジアの 10 言語にわたる 100 以上の人間に近い合成音声を導入\n• 主要な病院のコールセンターおよび公共部門で採用",
    "about.timeline_2026_title": "ウェブアバターとバーチャルヒューマン",
    "about.timeline_2026_desc": "• Web サイトの DOM 層に直接埋め込まれた 3D バーチャル ヒューマンをパイオニア\n• リアルタイム音声と対話型 Web ナビゲーションを備えた WebAvatar を開始\n• 自律的なページ ナビゲーション、スムーズなスクロール、動的な Web ルーティングを有効化",
    "about.competency_title": "私たちのコアコンピテンシー",
    "about.competency_subtitle": "Botnoi の研究部門によって社内で設計および保守されている独自のシステム。",
    "about.comp1_title": "カスタム東南アジアトークナイザー",
    "about.comp1_desc": "• 連続スクリプト言語 (タイ語、ラオス語、ビルマ語) の専用 NLP 解析\n• 明確な単語境界がない標準的な西洋 NLP の限界を克服\n• 最大 98% の精度で文のトークン化を実現",
    "about.comp2_title": "音響クローン合成音声",
    "about.comp2_desc": "• 30 分未満の高品質オーディオから人間の声のクローンを作成\n• 感情状態やペースをカスタマイズ可能な自然な音響を生成\n• ターゲットに適した地域のアクセントをサポート",
    "about.comp3_title": "マルチエージェントのコラボレーション",
    "about.comp3_desc": "• 特化した共同サブエージェント実行パイプラインを構築\n• 単一のアバター フロントエンド インターフェイスの下で無縫に動作\n• コンテキスト メモリ、トランザクション ロジック、DB アクションを調整",
    "about.comp4_title": "インタラクティブな DOM マッピング",
    "about.comp4_desc": "• リアルタイム ブラウザ DOM 反射と要素ポジショニングを統合\n• バーチャル エージェントが自動スクロールしてコンテンツを強調表示\n• 価格行、機能の内訳、対話型要素を口頭で説明",
    "about.team_title": "私たちのリーダーシップチーム",
    "about.team_subtitle": "当社の製品パイプライン、言語研究、地域のビジネス戦略を指揮する先見の明のある人たちを紹介します。",
    "about.team1_role": "創設者兼最高経営責任者",
    "about.team1_desc": "専門は計算ニューラルネットワークと地域ビジネス戦略。",
    "about.team2_role": "音声テクノロジー担当ディレクター",
    "about.team2_desc": "テキスト読み上げモデリングと感情的な音声クローン システムを監督します。",
    "about.team3_role": "自然言語処理責任者",
    "about.team3_desc": "東南アジアのトークン化と NLP パイプライン開発の中核となる研究開発を指揮します。",
    "about.team4_role": "WebAvatar 社リード プロダクト エンジニア",
    "about.team4_desc": "ブラウザ統合 SDK、レンダリング レイヤー、および SPA ルーティング プラグインを管理します。",
