    "contact.form_filling": "送信中...",
    "contact.faq_heading": "よくある質問",
    "contact.faq_subheading": "当社のサービスに関する簡単な回答をお読みください。 WebAvatar はここをスクロールして詳細を確認できます。",
    "contact.faq_q1": "WebAvatar とは何ですか? WebAvatar はどのように私のサイトに統合されますか?",
    "contact.faq_a1": "WebAvatar は、軽量の JavaScript SDK (カスタム スクリプト タグ) を介してロードされるビジュアル デジタル ヒューマン アシスタントです。標準のブラウザ Web レイヤー内で実行され、ページを移動したり、指定された HTML 要素 (#pricing など) までスクロールしたり、ネイティブのシングル ページ アプリ (SPA) ルートをトリガーしたり、合成音声を使用して訪問者を口頭でガイドしたりできます。",
    "contact.faq_q2": "音声モデルは連続的なタイの音響をサポートしていますか?",
    "contact.faq_a2": "はい。当社の生成音声モデルは、地域のオーディオ アーカイブでトレーニングされており、地元の聴衆に適した自然なペース、単語のブリッジング、声調の抑揚を備えた、連続的なタイの方言に対する豊富な音響マッピングを提供します。",
    "contact.faq_q3": "デジタル アバターの外観をカスタマイズできますか?",
    "contact.faq_a3": "絶対に。 Botnoi Group は、カスタム 3D モデル リグ、ビジュアル テーマ スキン、特殊なブランド表現をサポートしています。貴社のマスコット、著名人、仮想ブランドアンバサダーを直接モデルにしたアバターを作成できます。",
    "contact.faq_q4": "Botnoi Group の創設者は誰ですか?",
    "contact.faq_a4": "ウィン博士は、Botnoi Group の先見の明のある創設者兼最高経営責任者です。彼は、バンコクのワッタナにある本社で、当社の中核となる AI 研究部門、音声技術ラボ、デジタル ヒューマン アバターの統合を調整しています。",
