    "showcase.no_projects_desc": "検索フィルターまたはクエリを調整してみてください。",
    "showcase.desc_accommodation": "• リアルタイム客室カタログと空室検索\n• インタラクティブな日付選択と自動料金計算\n• 完全な予約確認と証明書表示",
    "showcase.desc_flight": "• 国内線フライト検索と乗客数設定\n• インタラクティブな座席マップと搭乗券生成\n• エンドツーエンドの航空券予約シミュレーション",
    "showcase.desc_restaurant": "• カテゴリ別デジタルメニュー注文\n• ショッピングカート管理と注文サマリー\n• 即時料金計算とリアルタイム請求書",
    "showcase.desc_ecommerce": "• 家電製品の展示とカテゴリフィルタリング\n• カート管理と注文決済手続き\n• リアルタイム請求書とデジタル領収書表示",
    "showcase.desc_tn01": "• コースカタログとビデオレッスン\n• 進捗トラッキングと対話型クイズ\n• 修了時の自動修了証発行",
    "showcase.desc_tn03": "• 肌診断とスキンケアルーティン案内\n• 肌タイプに合わせた成分フィルタリング\n• オンラインカートと決済注文確認",
    "showcase.desc_tn04": "• インタラクティブなルート検索とスポット案内\n• 旅程作成と移動時間見積もり\n• ランドマークと観光地のおすすめ",
    "showcase.desc_tn05": "• オンライン医師予約と診療科検索\n• 健康診断パッケージと医療機関案内\n• 個人健康記録と診断レポート",
    "showcase.desc_tn06": "• 音声認識（STT）、音声合成（TTS）、ボイスクローン\n• AIチャットボットと言語モデル API\n• 開発者向け SDK ドキュメントと料金プラン",
    "showcase.desc_tn07": "• デジタルメニューとオンラインテーブル予約\n• 味やトッピングのカスタム注文\n• リアルタイム注文サマリーと会計",
    "showcase.desc_tn08": "• バーチャルショールームと家具カタログ\n• インテリアデザイン提案と空間コーディネート\n• オンライン注文と決済システム",
    "showcase.desc_tn09": "• リアルタイム音声間双方向翻訳\n• 自然なテキスト読み上げ（TTS）と音声変換\n• 多言語音声再生と即時翻訳",
    "showcase.desc_tn10": "• エアコン洗浄・修理エンジニア派遣予約\n• 明朗なサービス料金と洗浄パッケージ\n• エンジニアの対応状況リアルタイム追跡",
    "showcase.desc_tn11": "• 専門薬剤師によるオンライン服薬相談\n• 初期症状チェックと処方薬のアドバイス\n• 安全な自宅配送サービス",
    "showcase.desc_tn12": "• 住宅・不動産検索プラットフォーム\n• バーチャル内覧と物件カタログ\n• エージェント相談とオンライン見学予約",
    "showcase.desc_tn14": "• スペシャルティコーヒー豆注文とカフェメニュー\n• 焙煎度、甘さ、トッピングのカスタマイズ\n• 事前注文受取とポイント還元",
    "showcase.desc_tn15": "• メディカルスパ＆ウェルネス予約アシスタント\n• 施術パッケージと専門家相談\n• オンライン予約と即時確定",
    "showcase.desc_tn16": "• フィットネス・トレーニング統合プラットフォーム\n• トレーナー予約とトレーニング記録追跡\n• 個別栄養アドバイスと meal planning",
    "showcase.desc_tn17": "• ECストア向け AI プラットフォーム\n• チャット応答、接客 closing、商品レコメンド\n• 24時間自動在庫確認とカスタマーケア",
    "showcase.desc_tn19": "• バーチャルショールームと家具カタログ\n• インテリアデザイン提案と空間コーディネート\n• オンライン注文と決済システム",
