    "home.rule2_title": "선언적 포커스 후크",
    "home.rule2_desc": "• 고유한 DOM ID(예: #nav-flight, #nav-contact)를 사용하여 요소 고정\n• 부드러운 스크롤링 및 초점 링 애니메이션 동적 트리거\n• 시각적 강조 표시를 아바타 음성과 동기화",
    "home.rule3_title": "중복 입력 검증",
    "home.rule3_desc": "• 클라이언트 측 양식을 표준 HTML5 입력 유효성 검사에 연결\n• 기본 입력 이벤트를 전달하여 React 구성 요소 상태 업데이트\n• 실시간 반응형 피드백 및 성공 표시기 제공",
