    "about.badge": "우리의 정체성",
    "about.title": "선구적인 대화 지능",
    "about.subtitle": "Botnoi Group은 동남아시아 기업을 위해 고급 인공 지능에 대한 접근성, 초지역화, 높은 거래성을 제공한다는 단 하나의 사명을 가지고 설립되었습니다.",
    "about.purpose_title": "우리의 목적",
    "about.purpose_desc1": "우리는 인간과 기계의 상호 작용이 마찰이 없고 자연스럽고 매우 직관적이어야 한다고 믿습니다. 대화형 NLP, 합성 인간 음향 및 대화형 3D 디지털 아바타를 연결함으로써 우리는 미래의 디지털 인력을 창출합니다.",
    "about.purpose_desc2": "빈도가 높은 고객 관리를 자동화하든 복잡한 의료 포털을 통해 환자를 안내하든 Botnoi Group 솔루션은 타협할 수 없는 안정성으로 확장되도록 구축되었습니다.",
    "about.vision_title": "우리의 비전",
    "about.vision_desc": "동남아시아 음성 및 디지털 휴먼 기술의 절대 표준이 됩니다. 우리는 지역 중소기업과 기업이 탁월한 고객 만족을 제공하는 최첨단 가상 에이전트를 배포할 수 있도록 지원합니다.",
    "about.vision_cta": "엔지니어와 연결",
    "about.journey_title": "보트노이의 여정",
    "about.journey_subtitle": "방콕의 전문 AI 스타트업에서 지역 디지털 휴먼 리더까지의 역사를 추적합니다.",
    "about.timeline_2018_title": "회사 설립",
    "about.timeline_2018_desc": "• 전산 언어학자 및 AI 엔지니어에 의해 태국 방콕에 Botnoi Group 설립\n• 전문 태국어 구문 분석 및 자연어 처리(NLP) 모델 구축에 집중",
    "about.timeline_2020_title": "Botnoi AI 출시",
    "about.timeline_2020_desc": "• 주력 로우코드 AI 챗봇 플랫폼(Botnoi.ai) 출시\n• LINE OA 및 Facebook Messenger 전반에 걸쳐 고객 지원 자동화 확장\n• 5,000개 이상의 기업 고객을 위한 자동화된 고객 지원 강화",
    "about.timeline_2022_title": "Botnoi 음성 롤아웃",
    "about.timeline_2022_desc": "• 최첨단 텍스트 음성 변환(TTS) 엔진(Botnoi Voice) 공개\n• 동남아시아 10개 언어에 인간에 가까운 100개 이상의 합성 음성 도입\n• 주요 병원 콜센터 및 공공 부문 채널에 채택",
    "about.timeline_2026_title": "Web아바타 및 가상 인간",
    "about.timeline_2026_desc": "• 웹사이트 DOM 레이어에 직접 내장된 3D 가상 인간 선도\n• 실시간 음성 및 대화형 웹 탐색 기능을 갖춘 WebAvatar 출시\n• 자율 페이지 탐색, 부드러운 스크롤 및 동적 웹 라우팅 활성화",
    "about.competency_title": "우리의 핵심 역량",
    "about.competency_subtitle": "Botnoi의 연구 부서가 자체적으로 설계하고 유지 관리하는 독점 시스템입니다.",
    "about.comp1_title": "맞춤형 동남아시아 토크나이저",
    "about.comp1_desc": "• 연속 스크립트 언어(태국어, 라오어, 버마어)에 특화된 NLP 구문 분석\n• 명확한 단어 경계가 부족한 서양 NLP 프레임워크의 한계 극복\n• 문장 토큰화 정확도 최대 98% 달성",
    "about.comp2_title": "어쿠스틱 복제 합성 보이스",
    "about.comp2_desc": "• 30분 미만의 고품질 오디오 샘플에서 사람 목소리 복제\n• 맞춤형 감정 상태 및 속도 변화를 통해 자연스러운 음향 생성\n• 타겟 청중에 적합한 현지화된 지역 악센트 지원",
    "about.comp3_title": "다중 에이전트 협업",
    "about.comp3_desc": "• 전문화된 협업 하위 에이전트 실행 파이프라인 구축\n• 단일 통합 아바타 프론트엔드 인터페이스 아래에서 원활하게 작동\n• 컨텍스트 메모리 데이터, 트랜잭션 로직 및 DB 작업 조정",
    "about.comp4_title": "대화형 DOM 매핑",
    "about.comp4_desc": "• 실시간 브라우저 DOM 반영 및 요소 포지셔닝 통합\n• 가상 에이전트가 페이지를 자동 스크롤하고 요청된 콘텐츠 강조 표시\n• 가격 행, 기능 내역 및 대화형 요소를 구두로 설명",
    "about.team_title": "우리의 리더십 팀",
    "about.team_subtitle": "당사의 제품 파이프라인, 언어학 연구 및 지역 비즈니스 전략을 지휘하는 선구자들을 만나보세요.",
    "about.team1_role": "창립자 겸 CEO",
    "about.team1_desc": "전산 신경망 및 지역 비즈니스 전략을 전문으로 합니다.",
    "about.team2_role": "음성 기술 이사",
    "about.team2_desc": "텍스트 음성 변환 모델링 및 감정적 음성 복제 시스템을 감독합니다.",
    "about.team3_role": "자연어 처리 책임자",
    "about.team3_desc": "동남아시아 토큰화 및 NLP 파이프라인 개발을 위한 핵심 R&D를 지휘합니다.",
    "about.team4_role": "WebAvatar 수석 제품 엔지니어",
    "about.team4_desc": "브라우저 통합 SDK, 렌더링 레이어 및 SPA 라우팅 플러그인을 관리합니다.",
