    "showcase.no_projects": "프로젝트를 찾을 수 없습니다",
    "showcase.no_projects_desc": "검색 필터 또는 쿼리를 조정해 보세요.",
    "showcase.desc_accommodation": "• 실시간 객실 카탈로그 및 빈 객실 검색\n• 대화형 날짜 선택 및 자동 요금 계산\n• 전체 예약 확인 및 인증서 뷰",
    "showcase.desc_flight": "• 국내선 항공편 검색 및 승객 정보 설정\n• 대화형 좌석 지정 및 모의 탑승권 생성\n• 엔드투엔드 항공사 예약 시뮬레이션",
    "showcase.desc_restaurant": "• 카테고리별 디지털 메뉴 주문\n• 장바구니 관리 및 주문 요약\n• 즉시 금액 계산 및 실시간 영수증",
    "showcase.desc_ecommerce": "• 가전 제품 쇼케이스 및 카테고리 필터링\n• 장바구니 관리 및 주문 결제 처리\n• 실시간 인보이스 및 디지털 영수증 확인",
    "showcase.desc_tn01": "• 강좌 카탈로그 및 비디오 강의\n• 진도 관리 및 대화형 퀴즈\n• 학습 완료 시 자동 수료증 발급",
    "showcase.desc_tn03": "• 피부 진단 및 스킨케어 루틴 추천\n• 피부 타입 맞춤형 성분 필터링\n• 장바구니 및 온라인 결제 확인",
    "showcase.desc_tn04": "• 경로 탐색 및 장소 검색\n• 일정 계획 및 이동 시간 계산\n• 주요 랜드마크 및 추천 방문지",
    "showcase.desc_tn05": "• 의사 진료 예약 및 진료과 안내\n• 건강검진 패키지 및 의료기관 목록\n• 개인 건강 기록 및 진단 보고서",
    "showcase.desc_tn06": "• 태국어 음성 인식(STT), 음성 합성(TTS) 및 보이스 클론\n• AI 대화 챗봇 및 언어 모델 API\n• 개발자 SDK 문서 및 구독 요금제",
    "showcase.desc_tn07": "• 디지털 메뉴판 및 온라인 테이블 예약\n• 옵션 맞춤 주문 및 재료 변경\n• 실시간 주문 요약 및 영수증 결제",
    "showcase.desc_tn08": "• 가상 쇼룸 및 가구 카탈로그\n• 인테리어 스타일링 아이디어 제안\n• 원스톱 온라인 주문 및 결제",
    "showcase.desc_tn09": "• 실시간 음성 대 음성 번역\n• 자연스러운 텍스트 음성 변환(TTS) 및 음성 합성\n• 다국어 오디오 재생 및 실시간 변환",
    "showcase.desc_tn10": "• 에어컨 청소 및 수리 기사 방문 예약\n• 투명한 서비스 요금 및 청소 패키지\n• 엔지니어 진행 현황 실시간 조회",
    "showcase.desc_tn11": "• 전문 약사의 온라인 복약 상담\n• 증상 사전 확인 및 약품 안내\n• 안전한 의약품 홈 배송 서비스",
    "showcase.desc_tn12": "• 부동산 및 주택 검색 플랫폼\n• 가상 매물 투어 및 프로젝트 카탈로그\n• 온라인 중개인 상담 및 방문 예약",
    "showcase.desc_tn14": "• 스페셜티 원두 주문 및 카페 메뉴\n• 로스팅, 당도, 토핑 맞춤 선택\n• 사전 픽업 주문 및 적립금 혜택",
    "showcase.desc_tn15": "• 메디컬 스파 및 웰니스 예약 도우미\n• 마사지 패키지 및 전문가 상담\n• 온라인 예약 및 즉시 확정",
    "showcase.desc_tn16": "• 통합 피트니스 및 트레이닝 플랫폼\n• 전담 트레이너 예약 및 운동 기록 관리\n• 맞춤형 영양 가이드 및 식단 계획",
    "showcase.desc_tn17": "• 온라인 쇼핑몰 전용 AI 플랫폼\n• 챗봇 응답, 판매 마무리 및 상품 추천\n• 24시간 자동 재고 확인 및 고객 케어",
    "showcase.desc_tn19": "• 가상 쇼룸 및 가구 카탈로그\n• 인테리어 스타일링 아이디어 제안\n• 원스톱 온라인 주문 및 결제",
