    "home.hero_subtitle": "Botnoi Group presenta el escaparate definitivo para agentes de WebAvatar. Esta zona de pruebas unificada presenta tres aplicaciones empresariales localizadas configuradas para voz automatizada, llenado de formularios y enrutamiento de páginas.",
