    "contact.form_submit": "Enviar consulta sobre Sandbox",
    "contact.form_filling": "Sumisión...",
    "contact.faq_heading": "Preguntas frecuentes",
    "contact.faq_subheading": "Lea respuestas rápidas sobre nuestros servicios. ¡Tu WebAvatar puede desplazarse aquí para revisar los detalles!",
    "contact.faq_q1": "¿Qué es WebAvatar y cómo se integra en mi sitio?",
    "contact.faq_a1": "WebAvatar es un asistente humano digital visual cargado a través de un SDK de JavaScript liviano (nuestra etiqueta de script personalizada). Se ejecuta dentro de las capas web estándar del navegador y puede navegar por páginas, desplazarse a elementos HTML designados (como #precios), activar rutas nativas de aplicaciones de página única (SPA) y guiar verbalmente a sus visitantes mediante voz sintética.",
    "contact.faq_q2": "¿El modelo de voz admite la acústica tailandesa continua?",
    "contact.faq_a2": "Sí. Nuestros modelos de voz generativa están entrenados en archivos de audio regionales y ofrecen un rico mapeo acústico para dialectos tailandeses continuos, completo con ritmo natural, puentes de palabras e inflexión de tonos apropiados para las audiencias locales.",
    "contact.faq_q3": "¿Puedo personalizar la apariencia visual del avatar digital?",
    "contact.faq_a3": "Absolutamente. Botnoi Group admite plataformas de modelos 3D personalizadas, máscaras de temas visuales y representaciones de marcas especializadas. Podemos crear un avatar modelado directamente a partir de la mascota de su empresa, figura pública o embajador virtual de su marca.",
    "contact.faq_q4": "¿Quién es el fundador ejecutivo del Grupo Botnoi?",
    "contact.faq_a4": "El Dr. Winn es el visionario fundador y director ejecutivo de Botnoi Group. Coordina nuestra división central de investigación de IA, laboratorios de tecnología del habla e integraciones de avatares humanos digitales desde nuestra sede en Watthana, Bangkok.",
