    "showcase.no_projects_desc": "Intente ajustar sus filtros de búsqueda o consultas.",
    "showcase.desc_accommodation": "• Catálogo de habitaciones en tiempo real y consulta de disponibilidad\n• Selección interactiva de fechas y cálculo automático de tarifas\n• Confirmación de reserva y vista de certificados",
    "showcase.desc_flight": "• Búsqueda de vuelos nacionales y configuración de pasajeros\n• Mapa de asientos interactivo y generación de tarjeta de embarque\n• Simulación completa de reserva de vuelos",
    "showcase.desc_restaurant": "• Menú digital categorizado para pedidos\n• Gestión de carrito y resumen de pedido\n• Cálculo de factura al instante y recibos en vivo",
    "showcase.desc_ecommerce": "• Catálogo de electrónica de consumo y filtros por categoría\n• Gestión de carrito de compras y proceso de pago\n• Facturación instantánea y recibos digitales",
    "showcase.desc_tn01": "• Catálogo integral de cursos y lecciones en línea\n• Seguimiento de progreso y cuestionarios interactivos\n• Certificación de cursos automatizada",
    "showcase.desc_tn03": "• Análisis dermatológico y guía de rutina de cuidado\n• Filtro de ingredientes adaptado al tipo de piel\n• Carrito en línea y confirmación de compra",
    "showcase.desc_tn04": "• Mapa de rutas interactivo y búsqueda de lugares\n• Planificación de itinerarios y estimación de tiempos\n• Recomendaciones de lugares emblemáticos y visitas",
    "showcase.desc_tn05": "• Cita médica en línea y directorio de especialidades\n• Paquetes de chequeo de salud y centro médico\n• Historial médico personal y resultados de análisis",
    "showcase.desc_tn06": "• Servicios de voz en tailandés (STT, TTS, Clonación de Voz)\n• Chatbot IA conversacional y API de modelos de lenguaje\n• Documentación SDK para desarrolladores y suscripciones",
    "showcase.desc_tn07": "• Menú digital y reserva de mesas en línea\n• Pedidos personalizados con ajuste de ingredientes\n• Resumen de compra y facturación al instante",
    "showcase.desc_tn08": "• Salas de exhibición virtuales y catálogo de muebles\n• Inspiración de diseño de interiores para espacios\n• Compra y pago en línea integrados",
    "showcase.desc_tn09": "• Traducción de voz a voz en tiempo real\n• Síntesis de voz natural (TTS) y conversión de voz\n• Reproducción de audio y traducción multilingüe",
    "showcase.desc_tn10": "• Agenda de técnicos de aire acondicionado y mantenimiento\n• Precios transparentes y paquetes de limpieza\n• Seguimiento en vivo del estado del servicio",
    "showcase.desc_tn11": "• Consulta en línea con farmacéuticos colegiados\n• Evaluación inicial de síntomas y orientación de fármacos\n• Servicio de entrega segura de medicamentos a domicilio",
    "showcase.desc_tn12": "• Plataforma de búsqueda de viviendas y bienes raíces\n• Muestras virtuales e itinerarios de proyectos\n• Consultas en línea con agentes y citas de visita",
    "showcase.desc_tn14": "• Pedidos de café de especialidad y menú de repostería\n• Selección personalizada de tueste, dulzor y aderezos\n• Pedidos anticipados y programa de puntos de fidelidad",
    "showcase.desc_tn15": "• Asistente de reservas de spa médico y bienestar\n• Paquetes de tratamiento y consultas con especialistas\n• Reserva de citas en línea con confirmación inmediata",
    "showcase.desc_tn16": "• Plataforma integral de entrenamiento y fitness\n• Agenda de ejercicios, reserva de entrenadores y progreso\n• Guía de nutrición y planificación de comidas",
    "showcase.desc_tn17": "• Plataforma de IA para tiendas de comercio electrónico\n• Respuestas de chatbot, cierre de ventas y recomendaciones\n• Verificación de stock 24/7 y atención automatizada",
    "showcase.desc_tn19": "• Salas de exhibición virtuales y catálogo de muebles\n• Inspiración de diseño de interiores para espacios\n• Compra y pago en línea integrados",
