    "nav.site2026": "SITE·2026",
    "site2026.title": "Page de l'événement SITE 2026",
    "site2026.badge": "Impact mondial de l’innovation : l’année de l’investissement",
    "site2026.hero_title": "Startup x Innovation Thaïlande Expo 2026",
    "site2026.hero_subtitle": "25 - 27 juin 2026 au Queen Sirikit National Convention Center (QSNCC)",
    "site2026.about_title": "À PROPOS DU SITE 2026",
    "site2026.about_desc": "L'Agence nationale de l'innovation (organisme public) ou NIA reconnaît l'importance de développer continuellement le système national d'innovation et l'écosystème des startups. Cette année, Startup x Innovation Thailand Expo 2026 ou SITE 2026 est organisée sous le concept « Global Innovation Impact : The Year of Investment » pour rassembler des réseaux d'innovation mondiaux, élever la coopération et promouvoir le partage des connaissances pour renforcer l'écosystème.",
    "site2026.objective_title": "Objectifs",
    "site2026.objective_1": "1. Élever la coopération en matière d’innovation entre tous les secteurs de l’écosystème (gouvernement, secteur privé, universités, associations), tant au niveau local qu’international.",
    "site2026.objective_2": "2. Créer des opportunités commerciales et soutenir les startups et les entreprises innovantes.",
    "site2026.objective_3": "3. Établir des réseaux internationaux d’affaires et d’innovation en Asie du Sud-Est et dans le monde pour soutenir l’expansion économique.",
    "site2026.activities_title": "PRINCIPALES ACTIVITÉS",
    "site2026.activity_forum_title": "Forum",
    "site2026.activity_forum_desc": "Séminaires pour partager les connaissances et les pratiques commerciales des entreprises innovantes à succès, axés sur la collaboration, l'intelligence artificielle et la durabilité.",
    "site2026.activity_exhibition_title": "Exposition",
    "site2026.activity_exhibition_desc": "Vitrine d'entreprises et de startups basées sur l'innovation pour créer des opportunités commerciales, augmenter les revenus et stimuler les investissements.",
    "site2026.activity_match_title": "Jumelage d'affaires",
    "site2026.activity_match_desc": "Activités de mise en relation d'entreprises pour générer des investissements et une expansion commerciale pour les startups et les entreprises basées sur l'innovation avec les grandes entreprises.",
    "site2026.activity_pitch_title": "Lancement",
    "site2026.activity_pitch_desc": "Plan d'affaires lançant une concurrence pour les startups en phase de démarrage et de croissance et les entreprises basées sur l'innovation.",
    "site2026.activity_pma_title": "Prix ​​du Premier ministre",
    "site2026.activity_pma_desc": "Cérémonie de remise de prix par le Premier ministre pour honorer les startups, les entreprises et les particuliers à fort potentiel qui soutiennent l'écosystème.",
    "site2026.agenda_title": "PROGRAMME DE L'ÉVÉNEMENT",
    "site2026.search_placeholder": "Rechercher des conférenciers, des sujets ou des événements...",
